1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	/** The Sphinx card: "1 point. 2 per type beyond three, else 1." */
9	const BASE_POINTS = 1;
10	const FREE_TYPES = 3;
11	const POINTS_PER_TYPE_BEYOND_FREE = 2;
12	const POINTS_WITHIN_FREE_TYPES = 1;
13	
14	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
15	
16	const countDistinctTypes = (army: Card[]): number =>
17	  new Set(army.map((card) => card.monster)).size;
18	
19	const typeBonus = (distinctTypes: number): number =>
20	  distinctTypes > FREE_TYPES
21	    ? POINTS_PER_TYPE_BEYOND_FREE * (distinctTypes - FREE_TYPES)
22	    : POINTS_WITHIN_FREE_TYPES;
23	
24	/**
25	 * Each Sphinx surveys the types around it — every card in the army but itself.
26	 * Exclusion is positional, not by identity: an army may hold the same card
27	 * object in two slots, and each occupant must still see the other.
28	 */
29	const cardsSurrounding = (army: Card[], sphinxIndex: number): Card[] =>
30	  army.filter((_, index) => index !== sphinxIndex);
31	
32	const scoreSphinxAt = (army: Card[], sphinxIndex: number): number =>
33	  BASE_POINTS +
34	  typeBonus(countDistinctTypes(cardsSurrounding(army, sphinxIndex)));
35	
36	export const scoreArmy = (army: Card[]): number =>
37	  army.reduce(
38	    (total, card, index) =>
39	      isSphinx(card) ? total + scoreSphinxAt(army, index) : total,
40	    0,
41	  );
