1	import { scoreArmy, type Card } from "./sphinx-score.js";
2	
3	/**
4	 * Minimal shape of the Node globals this entry point needs. Declared locally
5	 * because the project does not depend on @types/node.
6	 */
7	declare const process: {
8	  stdin: AsyncIterable<{ toString(encoding: string): string }> & {
9	    setEncoding(encoding: string): void;
10	  };
11	  stdout: { write(text: string): void };
12	};
13	
14	const readStdin = async (): Promise<string> => {
15	  process.stdin.setEncoding("utf8");
16	  let input = "";
17	  for await (const chunk of process.stdin) input += chunk;
18	  return input;
19	};
20	
21	const main = async (): Promise<void> => {
22	  const { army } = JSON.parse(await readStdin()) as { army: Card[] };
23	  process.stdout.write(`${JSON.stringify({ score: scoreArmy(army) })}\n`);
24	};
25	
26	await main();
