4	describe("Sphinx scoring", () => {
5	  it("scores 0 for an army with no Sphinx — Chimera, Orthrus, Zombie → 0", () => {
6	    expect(
7	      scoreArmy([
8	        { monster: "chimera" },
9	        { monster: "orthrus" },
10	        { monster: "zombie" },
11	      ]),
12	    ).toBe(0);
13	  });
14	  it("scores 2 for a Sphinx with fewer than three types — Sphinx, Cyclops → 2", () => {
15	    expect(scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }])).toBe(2);
16	  });
17	  it("scores 2 for a Sphinx counting itself among exactly three types — Sphinx, Chimera, Orthrus → 2", () => {
18	    expect(
19	      scoreArmy([
20	        { monster: "sphinx" },
21	        { monster: "chimera" },
22	        { monster: "orthrus" },
23	      ]),
24	    ).toBe(2);
25	  });
26	  it("scores 3 for a Sphinx with one type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3", () => {
27	    expect(
28	      scoreArmy([
29	        { monster: "sphinx" },
30	        { monster: "chimera" },
31	        { monster: "orthrus" },
32	        { monster: "zombie" },
33	        { monster: "hydra" },
34	      ]),
35	    ).toBe(3);
36	  });
