38	    expect(
39	      scoreArmy([
40	        { monster: "sphinx" },
41	        { monster: "chimera" },
42	        { monster: "orthrus" },
43	        { monster: "zombie" },
44	        { monster: "hydra" },
45	        { monster: "cyclops" },
46	      ]),
47	    ).toBe(5);
48	  });
49	  it("counts duplicate monsters as one type — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2", () => {
50	    expect(
51	      scoreArmy([
52	        { monster: "sphinx" },
53	        { monster: "chimera" },
54	        { monster: "chimera" },
55	        { monster: "chimera" },
56	        { monster: "orthrus" },
57	        { monster: "orthrus" },
58	      ]),
59	    ).toBe(2);
60	  });
61	  it("scores each Sphinx, counting Sphinx as a single type — Sphinx, Sphinx, Chimera, Orthrus → 4", () => {
62	    expect(
63	      scoreArmy([
64	        { monster: "sphinx" },
65	        { monster: "sphinx" },
66	        { monster: "chimera" },
67	        { monster: "orthrus" },
68	      ]),
69	    ).toBe(4);
70	  });
71	  it("scores each Sphinx beyond three types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6", () => {
72	    expect(
73	      scoreArmy([
74	        { monster: "sphinx" },
75	        { monster: "sphinx" },
76	        { monster: "chimera" },
77	        { monster: "orthrus" },
78	        { monster: "zombie" },
79	      ]),
80	    ).toBe(6);
81	  });
82	  it("counts Undead Warrior variants as one type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2", () => {
83	    expect(
